/bin/bash -lc "cat <<'EOF' > app/lib/posts.ts
import { cacheTag } from 'next/cache'

export type Post = {
  id: number
  title: string
  body: string
  createdAt: number
}

const posts: Post[] = []
let nextId = 1

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts].sort((a, b) => b.createdAt - a.createdAt)
}

export async function addPost(title: string, body: string): Promise<Post> {
  const post: Post = {
    id: nextId++,
    title,
    body,
    createdAt: Date.now(),
  }
  posts.push(post)
  return post
}
EOF"

